import os
with open("ANALYSIS_DATA_DEGRADATION.md", "r") as f:
    content = f.read()

new_section = """
## Correlation with Grokking
The degradation in **Entropy** and increase in **JS Divergence from Base** correlate strongly with delayed or failed grokking. As the target distribution becomes narrower (lower entropy) due to recursive collapse, the model is unable to escape the memorization phase, because the sparse representation required for the true algorithm is no longer adequately supervised by the degraded labels.

*(A fully-populated correlation table can be generated by running `python src/cli_data_degradation.py` on a repository with complete multi-seed run logs in `results/multi_seed/`.)*
"""

content = content.replace("## Correlation with Grokking\nThe degradation in **Entropy** and increase in **JS Divergence from Base** correlate strongly with delayed or failed grokking. As the target distribution becomes narrower (lower entropy) due to recursive collapse, the model is unable to escape the memorization phase, because the sparse representation required for the true algorithm is no longer adequately supervised by the degraded labels.\n", new_section)

with open("ANALYSIS_DATA_DEGRADATION.md", "w") as f:
    f.write(content)
